#include <vector>
#include <map>

class Solution {
public:
    bool isPossibleDivide(std::vector<int>& nums, int k) {
        if (nums.size() % k != 0) return false;
        std::map<int, int> counts;
        for (int x : nums) counts[x]++;
        for (auto& [x, count] : counts) {
            if (count > 0) {
                int need = count;
                for (int i = 0; i < k; ++i) {
                    if (counts[x + i] < need) return false;
                    counts[x + i] -= need;
                }
            }
        }
        return true;
    }
};

import java.util.*;

class Solution {
    public boolean isPossibleDivide(int[] nums, int k) {
        if (nums.length % k != 0) return false;
        TreeMap<Integer, Integer> counts = new TreeMap<>();
        for (int x : nums) counts.put(x, counts.getOrDefault(x, 0) + 1);
        for (int x : counts.keySet()) {
            int count = counts.get(x);
            if (count > 0) {
                for (int i = 0; i < k; i++) {
                    int curCount = counts.getOrDefault(x + i, 0);
                    if (curCount < count) return false;
                    counts.put(x + i, curCount - count);
                }
            }
        }
        return true;
    }
}

var isPossibleDivide = function(nums, k) {
    if (nums.length % k !== 0) return false;
    const counts = new Map();
    for (const x of nums) counts.set(x, (counts.get(x) || 0) + 1);
    const sortedKeys = Array.from(counts.keys()).sort((a, b) => a - b);
    for (const x of sortedKeys) {
        const count = counts.get(x);
        if (count > 0) {
            for (let i = 0; i < k; i++) {
                const cur = counts.get(x + i) || 0;
                if (cur < count) return false;
                counts.set(x + i, cur - count);
            }
        }
    }
    return true;
};
